package com.fitconnect.booking.api; import com.fitconnect.booking.service.ServiceUnavailableException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ProblemDetail> notFound(IllegalArgumentException e){return response(HttpStatus.BAD_REQUEST,e.getMessage());}@ExceptionHandler(IllegalStateException.class) ResponseEntity<ProblemDetail> conflict(IllegalStateException e){return response(HttpStatus.CONFLICT,e.getMessage());}@ExceptionHandler(ServiceUnavailableException.class) ResponseEntity<ProblemDetail> unavailable(ServiceUnavailableException e){return response(HttpStatus.SERVICE_UNAVAILABLE,e.getMessage());}private ResponseEntity<ProblemDetail> response(HttpStatus s,String d){return ResponseEntity.status(s).body(ProblemDetail.forStatusAndDetail(s,d));}}
